(()=>{'use strict';
const CARDS={
armoredshrimp:{n:'呪鱗の守り',i:'🛡️',c:1,b:9,curseBlock:3,curseCap:Infinity,unlock:1,upgrade:{b:4},t:'9ブロック。戦闘中の呪い1枚につき追加3ブロック。',g:'呪い・防御'},
sunfishcalm:{n:'供物の選別',i:'🐚',c:1,b:7,choice:'offering',r:1,unlock:3,upgrade:{b:2},t:'7ブロック。手札1枚を選んで廃棄。呪いなら追加6ブロック、それ以外なら1枚引く。',g:'廃棄・呪い'},
lanternpact:{n:'深淵との共生',i:'🏮',c:2,p:0,seedCurse:0,choice:'playDiscarded',a:1,unlock:3,upgrade:{c:-1},t:'手札を1枚選んで捨て、そのカードの効果をコストなしで発動する。',g:'捨て札・共生'},
gobysweep:{n:'呪牙の一刺し',i:'🦈',c:1,d:9,curseDamage:3,curseCap:Infinity,unlock:5,upgrade:{d:4},t:'9ダメージ。戦闘中の呪い1枚につき追加3ダメージ。',g:'呪い・攻撃'},
cleanerflow:{n:'脱皮する海流',i:'🌊',c:1,b:4,choice:'cycle',u:1,unlock:5,upgrade:{b:2},t:'4ブロック。手札1枚を選んで捨て、2枚引く。',g:'手札交換'},
nautilusreturn:{n:'沈没船の回収網',i:'⚓',c:1,b:6,choice:'recoverAny',r:1,unlock:7,upgrade:{b:3},t:'6ブロック。捨て札からカード1枚を選び、手札に戻す。回収カードは対象外。',g:'捨て札回収'},
voidtribute:{n:'反転術式',i:'🌀',c:2,d:0,curseDamage:0,curseCap:0,handCursePoison:0,curseInvert:1,exhaust:1,a:1,unlock:7,upgrade:{c:-1},t:'この戦闘中、ターン終了時の呪いダメージを同じ値のHP回復に反転する。使い切り。',g:'呪い・反転'},
flyingbreath:{n:'重荷を流す',i:'🐟',c:2,b:5,choice:'shed',unlock:9,upgrade:{c:-1},t:'5ブロック。手札1枚を選んで廃棄。呪いを廃棄したらエナジー1回復。',g:'廃棄・エナジー'}
};
window.ABYSS_ASCENSION_CARDS=CARDS;
const base=k=>String(k||'').replace(/~\d+$/,'').replace(/[+*]+$/,'');
const rarity=c=>c.a?'abyss':c.r?'rare':c.u?'uncommon':'common';
window.isAbyssCardUnlocked=k=>!CARDS[base(k)]||(window.getAbyssAscensionMeta?.().clears||[]).includes(CARDS[base(k)].unlock);
window.getAbyssUnlockCards=rank=>Object.keys(CARDS).filter(k=>CARDS[k].unlock===rank);
window.extendAbyssCardPool=(pool,tier)=>[...new Set([...pool,...Object.keys(CARDS).filter(k=>window.isAbyssCardUnlocked(k)&&(tier==='standard'?['common','uncommon'].includes(rarity(CARDS[k])):rarity(CARDS[k])===tier))])];
window.getAbyssCardUnlockMarkup=keys=>keys?.length?'<div class="card-unlock-reward"><b>新しいカードが解放されました</b><p>次の潜航から報酬・ショップなどに登場します。</p><div class="card-unlock-list unified-card-grid">'+keys.map(k=>window.renderAbyssCardView?.(k,{hideTag:true})||'').join('')+'</div></div>':'';
const isCurse=k=>window.getAbyssCardData?.(k)?.g==='呪い';
window.countAbyssCurses=g=>[...(g.draw||[]),...(g.hand||[]),...(g.discard||[])].filter(isCurse).length;
window.prepareAbyssUnlockCard=(c,g)=>{
 const count=Math.min(c.curseCap||0,window.countAbyssCurses(g));
 if(c.curseBlock)c.b+=count*c.curseBlock;
 if(c.curseDamage)c.d+=count*c.curseDamage;
 if(c.handCursePoison)c.p=Math.min(3,(g.hand||[]).filter(isCurse).length);
 if(c.seedCurse&&!g.curseSeeded){g.curseSeeded=true;g.discard.push('abysscurse')}
};
const recovering=kind=>kind.startsWith('recover');
function options(g){const pending=g.cardChoice;if(!pending)return[];const kind=pending.kind,from=kind==='dredge'?g.draw:recovering(kind)?g.discard:g.hand;if(kind==='dredge')return g.hand.length>=(window.abyssHandLimit?.(g)||8)?[]:from.map((k,index)=>({k,index})).slice(-3);if(recovering(kind)&&g.hand.length>=(window.abyssHandLimit?.(g)||8))return[];return from.map((k,index)=>({k,index})).filter(({k})=>{const c=window.getAbyssIntrinsicCardStats?.(k)||{};if(kind==='curseHand')return !isCurse(k);if(kind==='playDiscarded'&&base(k)==='lanternpact')return false;if(kind==='recoverCurse')return isCurse(k);if(recovering(kind)&&recovering(c.choice||''))return false;return kind!=='recoverSmall'||c.c<=1})}
function closeChoice(g){const pending=g.cardChoice;if(!pending)return;if(pending.secondaryKey)g.discard.push(pending.secondaryKey);if(pending.afterChoice){g.cardChoice=pending.afterChoice;window.abyssSave?.();window.resumeAbyssCardChoice?.();window.debugAbyssRefresh?.();return}if(pending.parentKey)g.discard.push(pending.parentKey);if(pending.repeatChoice>0){g.cardChoice={kind:pending.kind,key:pending.key,repeatChoice:pending.repeatChoice-1};window.abyssSave?.();window.resumeAbyssCardChoice?.();window.debugAbyssRefresh?.();return}if(pending.key)g.discard.push(pending.key);delete g.cardChoice;g.cardBusy=false;g.cardBusyAt=0;document.getElementById('curseCardChoice')?.classList.remove('on');window.abyssSave?.();window.debugAbyssRefresh?.()}
window.cancelAbyssCardChoice=closeChoice;
window.selectAbyssCardChoice=index=>{const g=window.getAbyssGame?.(),pending=g?.cardChoice;if(!pending)return;const chosen=options(g).find(o=>o.index===index);if(index!==null&&!chosen)return;if(chosen){const kind=pending.kind,curse=isCurse(chosen.k);if(kind==='curseHand'){g.hand[chosen.index]='abysscurse'}else if(kind==='dredge'){const top=g.draw.splice(Math.max(0,g.draw.length-3));const selected=top.splice(chosen.index-g.draw.length,1)[0];g.hand.push(window.abyssRandomizeDrawCost?.(selected)||selected);g.discard.push(...top);if(top.length)window.tacticalCardMoved?.(g,'discard')}else if(recovering(kind)){g.discard.splice(chosen.index,1);g.hand.push(chosen.k);if(kind==='recoverCurse')window.drawAbyssCards?.(2)}else if(kind==='playDiscarded'){g.hand.splice(chosen.index,1);window.tacticalCardMoved?.(g,'discard');const replay=window.getAbyssCardStats?.(chosen.k);window.resolveAbyssCardEffect?.(replay,chosen.k);if(replay?.choice){const after=pending.repeatChoice>0?{kind:'playDiscarded',key:pending.key,repeatChoice:pending.repeatChoice-1}:null;g.cardChoice={kind:replay.choice,key:null,secondaryKey:chosen.k,afterChoice:after,parentKey:after?null:pending.key};window.abyssSave?.();window.resumeAbyssCardChoice?.();return}g.discard.push(chosen.k)}else{g.hand.splice(chosen.index,1);if(kind==='cycle'){g.discard.push(chosen.k);window.drawAbyssCards?.(2);window.tacticalCardMoved?.(g,'discard')}else{(g.exhausted||=[]).push(chosen.k);window.tacticalCardMoved?.(g,'exhaust');if(kind==='offering'){if(curse){g.block+=6;if(g.runStats)g.runStats.blockGained+=6}else window.drawAbyssCards?.(1)}if(kind==='shed'&&curse&&!g.curseEnergyUsed){g.curseEnergyUsed=true;g.energy+=1}}}}closeChoice(g)};
window.resumeAbyssCardChoice=()=>{const g=window.getAbyssGame?.();if(!g?.cardChoice)return;if(!g.enemy||g.enemy.hp<=0){closeChoice(g);return}let modal=document.getElementById('curseCardChoice');if(!modal){modal=document.createElement('div');modal.id='curseCardChoice';modal.className='modal';document.body.appendChild(modal)}const list=options(g),kind=g.cardChoice.kind;modal.innerHTML='<div class="panel modal-shell"><header class="modal-shell-head"><div><h2>'+({curseHand:'呪いに変換する手札を選ぶ',dredge:'山札の上3枚から1枚選ぶ',playDiscarded:'捨てて発動するカードを選ぶ',recoverSmall:'捨て札から1枚回収',recoverAny:'捨て札から1枚回収',recoverCurse:'呪いを1枚回収',cycle:'手札を1枚捨てる',offering:'手札を1枚廃棄',shed:'手札を1枚廃棄'}[kind])+'</h2><p>'+(kind==='curseHand'?'選んだ手札は、この戦闘中だけ呪いになります。戦闘終了後は元のカードに戻ります。':kind==='playDiscarded'?'選んだカードは捨て札へ送り、コストなしで効果を発動します。':'廃棄したカードは、この戦闘中だけ戻りません。手札の上限は'+(window.abyssHandLimit?.(g)||8)+'枚です。')+'</p></div></header><div class="modal-shell-body curse-choice-list">'+(list.length?list.map(({k,index})=>{const c=window.getAbyssCardStats(k);return `<button type="button" data-choice-index="${index}"><b>${c.i} ${c.n}</b><small>コスト ${c.c}</small><span>${c.t}</span></button>`}).join(''):'<p>選べるカードがありません。</p>')+'</div><footer class="modal-shell-foot"><button type="button" data-choice-skip>選ばずに続ける</button></footer></div>';modal.querySelectorAll('[data-choice-index]').forEach(b=>b.onclick=()=>window.selectAbyssCardChoice(+b.dataset.choiceIndex));modal.querySelector('[data-choice-skip]').onclick=()=>window.selectAbyssCardChoice(null);modal.classList.add('on');window.applyFuri?.(modal)};
window.openAbyssCardChoice=(c,g,k,repeatChoice=0)=>{if(c.choice==='dredge'&&!g.draw.length){g.draw=g.discard.sort(()=>Math.random()-.5);g.discard=[]}g.cardChoice={kind:c.choice,key:k,repeatChoice};window.abyssSave?.();window.resumeAbyssCardChoice()};
})();
